class BankAccount:
    def __init__(self, owner, balance=0):
        self.owner = owner
        self.balance = balance

    def deposit(self, amount):
        self.balance += amount
        return self.balance

acct = BankAccount("Alex", 100)
acct.deposit(50)
print(acct.owner + ": $" + str(acct.balance))

def announce(func):
    def wrapper(*args, **kwargs):
        print("Executing function...")
        return func(*args, **kwargs)
    return wrapper

@announce
def ping():
    return "PONG"

print(ping())

